// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.junit.jupiter.api.Test;

class FrontierCountMinMatrixTest {

	@Test
	void scalarAndBatchedConstructionPreserveAllNonemptyMasksAndPlaneTotals() {
		List<long[]> tuples = List.of(
				new long[] { 11L, 3L, 101L, 0L },
				new long[] { 12L, 3L, 102L, 0L },
				new long[] { 13L, 4L, 103L, 17L },
				new long[] { 14L, 4L, 104L, 18L });
		FrontierCountMinMatrix scalar = new FrontierCountMinMatrix(3, 32);
		FrontierCountMinMatrix batched = new FrontierCountMinMatrix(3, 32);
		long[] subjects = new long[tuples.size()];
		long[] predicates = new long[tuples.size()];
		long[] objects = new long[tuples.size()];
		long[] contexts = new long[tuples.size()];
		long[] keys = new long[tuples.size()];
		int[] buckets = new int[tuples.size()];
		long[] componentHashes = new long[FrontierOmniLayout.COMPONENT_COUNT];

		for (int plane = 0; plane < 2; plane++) {
			for (int row = 0; row < tuples.size(); row++) {
				long[] tuple = tuples.get(row);
				scalar.add(plane, tuple[0], tuple[1], tuple[2], tuple[3]);
				FrontierStatisticsHash.componentHashes(tuple[0], tuple[1], tuple[2], tuple[3], componentHashes, 0);
				subjects[row] = componentHashes[0];
				predicates[row] = componentHashes[1];
				objects[row] = componentHashes[2];
				contexts[row] = componentHashes[3];
			}
			batched.addMasks(plane, 1, FrontierLeafProbe.ALL_COMPONENTS + 1,
					subjects, predicates, objects, contexts, tuples.size(), keys, buckets);
			batched.addRows(plane, tuples.size());
		}

		for (int plane = 0; plane < 2; plane++) {
			assertEquals(tuples.size(), scalar.total(plane));
			assertEquals(scalar.total(plane), batched.total(plane));
			for (int mask = 1; mask <= FrontierLeafProbe.ALL_COMPONENTS; mask++) {
				assertArrayEquals(scalar.copyCounters(plane, mask), batched.copyCounters(plane, mask),
						"plane=" + plane + ", mask=" + mask);
			}
		}

		assertThrows(IllegalArgumentException.class, () -> scalar.copyCounters(0, 0));
		assertThrows(IllegalArgumentException.class,
				() -> scalar.copyCounters(0, FrontierLeafProbe.ALL_COMPONENTS + 1));
		assertTrue(scalar.copyCounters(0, 1).length > 0);
	}

	@Test
	void heapAccountingChargesOnlyThirtyNonemptyTables() {
		FrontierStatisticsBuildConfig small = FrontierStatisticsBuildConfig.testing(
				32L * 1024 * 1024, 8, 16, 64, 1024L * 1024);
		FrontierStatisticsBuildConfig deeper = new FrontierStatisticsBuildConfig(
				small.diskBudgetBytes(), small.exactAndLinearBudgetBytes(), small.leafWitnessBudgetBytes(),
				small.joinSampleBudgetBytes(), small.adaptiveBudgetBytes(), small.deltaAndManifestBudgetBytes(),
				small.sortMemoryBytes(), small.designLaneCount(), small.auditLaneCount(), small.cellCount(),
				small.omniDepth(), small.witnessFloorPerCell(), small.witnessCeilingPerCell(),
				small.deleteReserveFraction(),
				small.countMinDepth() + 1, small.countMinWidth(), small.heavyPredicateCapacity(), small.hllPrecision());
		assertEquals(30L * small.countMinWidth() * Long.BYTES,
				FrontierStatisticsBuilder.estimatedHeapBytes(deeper)
						- FrontierStatisticsBuilder.estimatedHeapBytes(small));
	}

}
